css:
.pc-table { width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 0.92em; }
.pc-table th, .pc-table td { border: 1px solid #ccc; padding: 6px 8px; }
.pc-table th { background: #f5f5f5; }
.en { text-align: left; }
.ar { text-align: right; direction: rtl; font-family: 'Traditional Arabic', 'Arial', sans-serif; }
.pc-totals { width: 60%; margin-left: auto; margin-top: 15px; }
.pc-totals td { padding: 4px 8px; }
.pc-totals .grand { font-weight: bold; border-top: 2px solid #333; font-size: 1.1em; }
.pc-header { text-align: center; margin-bottom: 15px; }
.pc-party { width: 100%; margin: 10px 0; }
.pc-party td { vertical-align: top; padding: 4px; }
.sign { margin-top: 40px; width: 100%; }
.sign td { border-top: 1px solid #333; padding-top: 5px; font-size: 0.85em; }
.words { margin-top: 10px; font-size: 0.85em; }
.ar-line { direction: rtl; color: #444; font-size: 0.9em; }
